// NIO：一个线程管理多个连接
Selector selector = Selector.open();
ServerSocketChannel ssc = ServerSocketChannel.open();
ssc.bind(new InetSocketAddress(8081)).configureBlocking(false);
ssc.register(selector, SelectionKey.OP_ACCEPT);
while (true) {
    selector.select();                                    // 阻塞直到有就绪事件
    Iterator<SelectionKey> it = selector.selectedKeys().iterator();
    while (it.hasNext()) {
        SelectionKey key = it.next(); it.remove();
        if (key.isAcceptable()) {
            SocketChannel sc = ssc.accept();
            sc.configureBlocking(false).register(selector, SelectionKey.OP_READ);
        } else if (key.isReadable()) {
            ByteBuffer buf = ByteBuffer.allocate(1024);
            if (((SocketChannel) key.channel()).read(buf) < 0) key.channel().close();
        }
    }
}

import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.*;

public class BufferDemo {
    public static void main(String[] args) throws Exception {
        ByteBuffer buf = ByteBuffer.allocate(8);
        buf.put((byte) 'h').put((byte) 'i');      // 写模式：position=2, limit=8
        buf.flip();                               // 切换读模式：position=0, limit=2
        while (buf.hasRemaining()) System.out.print((char) buf.get());
        buf.clear();                              // 准备再次写入

        // 零拷贝复制文件
        try (FileChannel in = FileChannel.open(Path.of("a.log"), StandardOpenOption.READ);
             FileChannel out = FileChannel.open(Path.of("b.log"),
                     StandardOpenOption.CREATE, StandardOpenOption.WRITE)) {
            long pos = 0, size = in.size();
            while (pos < size) pos += in.transferTo(pos, size - pos, out);
        }
    }
}

EventLoopGroup boss = new NioEventLoopGroup(1);
EventLoopGroup worker = new NioEventLoopGroup();          // 默认 CPU 核数 * 2
EventExecutorGroup bizGroup = new DefaultEventExecutorGroup(16); // 耗时业务线程
try {
    new ServerBootstrap()
        .group(boss, worker)
        .channel(NioServerSocketChannel.class)
        .childOption(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
        .childHandler(new ChannelInitializer<SocketChannel>() {
            @Override protected void initChannel(SocketChannel ch) {
                ch.pipeline()
                  .addLast(new LengthFieldBasedFrameDecoder(1 << 20, 0, 4, 0, 4)) // 解决粘包拆包
                  .addLast(new StringDecoder(), new StringEncoder())
                  .addLast(bizGroup, new SimpleChannelInboundHandler<String>() {   // 业务不阻塞 IO 线程
                      @Override protected void channelRead0(ChannelHandlerContext ctx, String msg) {
                          ctx.writeAndFlush("echo:" + msg);
                      }
                  });
            }
        })
        .bind(9000).sync().channel().closeFuture().sync();
} finally {
    boss.shutdownGracefully(); worker.shutdownGracefully();
}

// Netty 中空轮询规避逻辑（简化示意，摘自其思路）
int selectCnt = 0;
long start = System.nanoTime();
while (true) {
    int selected = selector.select(timeoutMillis);
    selectCnt++;
    if (selected != 0 || hasTasks() || wakenUp) break;          // 正常返回
    long elapsed = System.nanoTime() - start;
    if (elapsed >= TimeUnit.MILLISECONDS.toNanos(timeoutMillis)) {
        selectCnt = 1;                                          // 正常超时，重新计数
    } else if (selectCnt >= SELECTOR_AUTO_REBUILD_THRESHOLD) {  // 默认 512
        selector = rebuildSelector(selector);                   // 新建 Selector 并迁移 Channel
        selectCnt = 1;
    }
    start = System.nanoTime();
}

